// Size, distinguishing. One trial. The mirror's 0x9a41[0] is 4.
// Legacy 0xdfa1 and the live 0x9a41[0] stay 0. The seed is test setup.
// The behaviour change is the combined profile read already in the overlay.
// EMULATOR-ONLY. Role: behaviour. Do not edit this file after it has run.
// Usage: node26 work/scripts/exp_size_v1.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/exp_size_v1.mjs om-emu\n');
  process.exit(2);
}
let API_SET = 0;
async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
const GET = 0x60063380;
const SET = 0x60063431;
const CONVERTER = 0x604050e5;
const MIRROR = 0xa031eeb0;
const MIRROR_C = 0x6031eeb0;
const ZONE = 0xa031e920;
const POSE = 0xa32c568c;
const RET_ZONE = 0x60a8f71c;
const RET_SIZE = 0x60a8f757;
const RET_POS = 0x60a8f76e;
const RET_PLUS9 = 0x60a8f789;
const CALL_CONV = 0x60a8f71f;
const BACK_CONV = 0x60a8f726;
const ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL4 = [0x11, 0x02, 0x03, 0x04, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const EDGES = [['s1', 'down'], ['s1', 'up'], ['afon', 'down'], ['afon', 'up']];
const OWNERS = [1, 0, 2, 0];
const AFON = new Set([2]);
const HALF_CELLS = {
  k99a1: [0, 0, 2, 0, 2, 0, 5, 5],
  k9a41: 0,
  k84d1: 2,
  k88b2: 526,
  k5962: [526, 526, 526, 526, 526, 526],
  k1dd1: [1, 1, 3, 3, 3, 3, 3, 3, 3, 3],
  k1df1: [1, 1, 1, 1, 0, 0, 0, 0],
  k1e01: 0,
  kdfa1: 0,
  k99d2: [526, 526, 526],
  k90a1: [1, 1],
  k1db1: 0,
  k1dc1: 0,
};
const OUT = resolve('work/out/size-v1.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ id: row.id, pass: row.pass, problems: row.problems || null }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function readKey(ctx, key, index) {
  return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}
function setKey(ctx, key, index, value) {
  ctx.l.call(ctx.native(SET), { d0: key, d1: index, a1: value }, null, null, 200000);
  const back = readKey(ctx, key, index);
  if (back !== (value & 0xffff)) throw new Error('setter readback ' + key.toString(16) + ' ' + back);
}
function setPublic(ctx, sid, value) {
  const argument = ctx.l.call(ctx.native(CONVERTER), { d0: sid, d1: value }, null, null, 200000).d0 >>> 0;
  ctx.l.call(API_SET, { d0: sid, d1: argument }, null, null, 200000);
  ctx.idle(400);
}
function half(ctx) {
  return {
    k99a1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x99a1, i)),
    k9a41: readKey(ctx, 0x9a41, 0),
    k84d1: readKey(ctx, 0x84d1, 0),
    k88b2: readKey(ctx, 0x88b2, 0),
    k5962: Array.from({ length: 6 }, (_, i) => readKey(ctx, 0x5962, i)),
    k1dd1: Array.from({ length: 10 }, (_, i) => readKey(ctx, 0x1dd1, i)),
    k1df1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x1df1, i)),
    k1e01: readKey(ctx, 0x1e01, 0),
    kdfa1: readKey(ctx, 0xdfa1, 0),
    k99d2: [0, 1, 2].map((i) => readKey(ctx, 0x99d2, i)),
    k90a1: [readKey(ctx, 0x90a1, 0), readKey(ctx, 0x90a1, 1)],
    k1db1: readKey(ctx, 0x1db1, 0),
    k1dc1: readKey(ctx, 0x1dc1, 0),
  };
}
function mirrorBytes(ctx) { return Array.from(ctx.l.sim.read(MIRROR, 55)); }
function sizeMirror() {
  const m = new Uint8Array(55);
  m[1] = 2;
  m[0x08] = 4;
  m[0x0c] = 529 & 0xff;
  m[0x0d] = (529 >> 8) & 0xff;
  m[0x22] = 529 & 0xff;
  m[0x23] = (529 >> 8) & 0xff;
  return Array.from(m);
}
function seed(ctx, bytes) {
  const buf = Buffer.from(bytes);
  ctx.l.sim.write(MIRROR, buf);
  ctx.l.sim.write(MIRROR_C, buf);
}
function pokeAll(ctx) {
  setKey(ctx, 0x84d1, 0, 2);
  setKey(ctx, 0x1dd1, 0, 1);
  setKey(ctx, 0x1dd1, 1, 1);
  setKey(ctx, 0x99a1, 0, 0);
}
function installProfileRead(ctx) {
  const link = { area: 0, pos: 0 };
  let inConv = false;
  const counts = { zone: 0, size: 0, pos: 0, plus9: 0, dim: 0 };
  const u8 = (a) => ctx.l.sim.read(a, 1)[0];
  const u16 = (a) => { const b = ctx.l.sim.read(a, 2); return b[0] | (b[1] << 8); };
  const bank = () => {
    if (!(link.area === 1 && link.pos === 1)) return 1;
    const pose = ctx.l.sim.u32(POSE) >>> 0;
    if (pose === 2) return 5;
    if (pose === 4) return 3;
    return 1;
  };
  const refresh = () => {
    link.area = readKey(ctx, 0x1db1, 0);
    link.pos = readKey(ctx, 0x1dc1, 0);
  };
  ctx.l.observe(ctx.native(CALL_CONV), () => { inConv = true; }, 'obs-builder-converter');
  ctx.l.observe(ctx.native(BACK_CONV), () => { inConv = false; }, 'obs-builder-converter-back');
  ctx.l.hook(ctx.native(GET), (h, r) => {
    const back = r.mdr >>> 0;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    const b = bank();
    if (back === RET_ZONE) {
      counts.zone += 1;
      let v = u8(MIRROR + b);
      if (v === 0xff) v = u8(ZONE);
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_SIZE) {
      counts.size += 1;
      let v = u8(MIRROR + 0x08);
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_POS) {
      counts.pos += 1;
      let v = u16(MIRROR + 0x0a + b * 2);
      if (v === 0xffff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_PLUS9) { counts.plus9 += 1; h.finish(r, { d0: 0 }); return; }
    if (inConv && key === 0x1dd1) {
      counts.dim += 1;
      let v = u8(MIRROR + 0x16 + (index & 0xff));
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    ctx.l.passthrough(r);
  }, 'EMULATOR-ONLY profile read from the mirror. Role: behaviour.');
  return { refresh, counts };
}
function check(id, problems, extra) {
  emit({ id, pass: problems.length === 0, problems, ...extra });
  if (problems.length) throw new Error(id + ' ' + problems.join(','));
}

const seeded = sizeMirror();

try {
  emit({
    id: 'size-v1-plan', step: 'plan', pass: true,
    note: 'One trial. Mirror 0x9a41[0] is 4. Legacy 0xdfa1 and live 0x9a41[0] stay 0. AF-ON target byte 3 is the mirror. Half-press target byte 3 is the legacy 0. Seed is test setup. EMULATOR-ONLY. Role: behaviour.',
    all: ALL, small4: SMALL4, mirror: seeded,
  });
  let hook = null;
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-size-v1.jsonl',
    tag: 'size-v1',
    candidate: true,
    help: true,
    rowLabel: true,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    fatalShots: true,
    explanation: 'Size trial. Combined profile read already in the overlay. Mirror size 4 is test setup. EMULATOR-ONLY. Role: behaviour.',
    change: 'combined profile read, already in the overlay',
    async drive(ctx) {
      await bindApi();
      hook = installProfileRead(ctx);
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(400);
      setPublic(ctx, 289, 0);
      if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) throw new Error('focus not S-AF');
      pokeAll(ctx);
      seed(ctx, seeded);
      hook.refresh();
      const gotHalf = half(ctx);
      const gotMirror = mirrorBytes(ctx);
      const dfa1 = readKey(ctx, 0xdfa1, 0);
      const live0 = readKey(ctx, 0x9a41, 0);
      const live1 = readKey(ctx, 0x9a41, 1);
      const setupProblems = [];
      if (readKey(ctx, 0x1e71, 0) !== 0) setupProblems.push('subject');
      if (!same(gotHalf, HALF_CELLS)) setupProblems.push('half');
      if (!same(gotMirror, seeded)) setupProblems.push('mirror');
      if (!same(Array.from(ctx.l.sim.read(MIRROR_C, 55)), seeded)) setupProblems.push('mirror-cached');
      if (dfa1 !== 0) setupProblems.push('dfa1');
      if (live0 !== 0) setupProblems.push('live-9a41');
      if (gotMirror[0x08] !== 4) setupProblems.push('mirror-size');
      if (dfa1 === gotMirror[0x08]) setupProblems.push('not-distinct');
      check('size-v1-setup', setupProblems, {
        step: 'setup',
        expected: {
          half: HALF_CELLS, mirror: seeded, dfa1: 0, k9a41_0: 0, mirrorSize: 4,
          subject: 0, focus: 0, active: 0,
        },
        actual: {
          half: gotHalf, mirror: gotMirror, dfa1, k9a41_0: live0, k9a41_1: live1,
          mirrorSize: gotMirror[0x08], subject: readKey(ctx, 0x1e71, 0),
          focus: ctx.s.get(289), active: ctx.s.get(25), zone: ctx.readByte(ZONE),
        },
      });
      for (let i = 0; i < EDGES.length; i++) {
        hook.refresh();
        const sizeBefore = hook.counts.size;
        ctx.key(EDGES[i][0], EDGES[i][1]);
        ctx.idle(250);
        const shot = ctx.shot('size-v1-e' + i);
        const own = ctx.readOwn();
        const target = ctx.readTarget();
        const nowHalf = half(ctx);
        const nowMirror = mirrorBytes(ctx);
        const nowDfa = readKey(ctx, 0xdfa1, 0);
        const nowLive = readKey(ctx, 0x9a41, 0);
        const nowLive1 = readKey(ctx, 0x9a41, 1);
        const afon = AFON.has(i);
        const want = afon ? SMALL4 : ALL;
        const problems = [];
        if (!same(target, want)) problems.push('target');
        if (target[3] !== (afon ? 4 : 0)) problems.push('size-byte');
        if (afon && target[3] === nowDfa) problems.push('afon-used-legacy');
        if (!afon && target[3] !== nowDfa) problems.push('half-not-legacy');
        if (nowDfa !== 0) problems.push('dfa1');
        if (nowLive !== 0) problems.push('live-9a41');
        if (nowLive1 !== live1) problems.push('live-9a41-1');
        if (nowMirror[0x08] !== 4) problems.push('mirror-size');
        if (own[4] !== OWNERS[i]) problems.push('owner');
        if (own[5] !== 0) problems.push('status');
        if (own[6] !== 1) problems.push('enabled');
        if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) problems.push('focus');
        if (readKey(ctx, 0x1e71, 0) !== 0) problems.push('subject');
        if (!same(nowHalf, HALF_CELLS)) problems.push('half');
        if (!same(nowMirror, seeded)) problems.push('mirror');
        if (afon && hook.counts.size <= sizeBefore) problems.push('size-unread');
        check('size-v1-e' + i, problems, {
          step: 'edge', key: EDGES[i][0], dir: EDGES[i][1],
          expected: {
            target: want, sizeByte: afon ? 4 : 0,
            sizeSource: afon ? 'mirror 0x9a41[0]' : 'legacy 0xdfa1',
            dfa1: 0, k9a41_0: 0, k9a41_1: live1, mirrorSize: 4,
            owner: OWNERS[i], status: 0, enabled: 1, focus: 0, active: 0,
            subject: 0, half: HALF_CELLS, mirror: seeded,
          },
          actual: {
            target, sizeByte: target[3],
            dfa1: nowDfa, k9a41_0: nowLive, k9a41_1: nowLive1, mirrorSize: nowMirror[0x08],
            owner: own[4], status: own[5], enabled: own[6],
            focus: ctx.s.get(289), active: ctx.s.get(25),
            subject: readKey(ctx, 0x1e71, 0), half: nowHalf, mirror: nowMirror,
            sizeReads: hook.counts.size, sizeReadsBefore: sizeBefore,
            screenshot: shot.file.split(/[/\\]/).pop(),
          },
        });
      }
      emit({
        id: 'size-v1-hook', step: 'hook', pass: hook.counts.size > 0, problems: hook.counts.size > 0 ? [] : ['size-unread'],
        counts: hook.counts,
      });
      if (hook.counts.size === 0) throw new Error('size-v1-hook size-unread');
    },
  });
  emit({ id: 'size-v1-session', step: 'session', pass: result.ok, failed: result.failed || null });
  if (!result.ok) throw new Error('size session failed');
  emit({ id: 'size-v1-done', step: 'done', pass: true, ok: true });
} catch (error) {
  emit({ id: 'size-v1-done', step: 'done', pass: false, ok: false, error: String(error && error.stack ? error.stack : error) });
  process.exit(1);
}
